"""Write docs/data_quality.md from the checks in emporio.quality.

Usage: python scripts/data_quality.py
"""

from emporio.config import ROOT
from emporio.data import load_store
from emporio.quality import MANUAL_FINDINGS, quality_report


def main() -> None:
    store = load_store(ROOT / "data" / "raw")
    lines = [
        "# Data quality report",
        "",
        "Generated by `scripts/data_quality.py`. Nothing here is edited in the source files: the agent",
        "works around each finding and the store team can fix the source.",
        "",
        "## Operational data",
        "",
        "| Where | Finding |",
        "|---|---|",
    ]
    lines += [f"| {where} | {finding} |" for where, finding in quality_report(store)]
    lines += ["", "## Policy manual", "", "| Where | Finding |", "|---|---|"]
    lines += [f"| {where} | {finding} |" for where, finding in MANUAL_FINDINGS]
    out = ROOT / "docs" / "data_quality.md"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
